select  from support_ticket where member_id=#{memberId}
 and id < #{beforeId}
order by id desc limit #{limit}

select id,event_type,actor_type,result_state,historical_status,historical_sla_state,historical_version,reason,request_id,message_id,created_at
from support_ticket_event where ticket_id=#{ticketId}
 and id < #{beforeId}
order by id desc limit #{limit}
